local function ReturnData()
	local Data = {};
	for _,v in ipairs(Dumbs) do table.insert(Data, v) end;
	for _,b in ipairs(Data) do
		b["Information"].DelayTime = 3;
		b["RarityData"] = (Rarities:GetRarityData(b["RarityType"], "Dumb"));
		Rarities:ApplyExtraData(b, "Dumbs");
		local Information = b["Information"];
		local RarityInfo = b["RarityInfo"];
		local TradeStatus = "Yes";
		if(b["Non-Tradable"])then TradeStatus = "No" end;
		b["Perk"] = "Gives "..Formatter.formatToGameStyle(b["Strength"]).." Strength Per Click With A Delay Time ("..tostring(Information.DelayTime)..")s. Rarity: "..tostring(RarityInfo.RarityType);
		b["InventoryData"] = {
			{Name = "Strength:", Value = Formatter.formatToGameStyle(b["Strength"])};
			{Name = "Delay Time:", Value = tostring(Information.DelayTime).."(s)"};
			{Name = "Description:", Value = b["Description"]};
