local function ReturnData()
	local Data = {};
	for i,v in ipairs(Stages) do table.insert(Data, v) end;
	for a,b in ipairs(Data) do
		Rarities:ApplyExtraData(b, "Pets");
		b["Index"] = a;
		b["RarityData"] = (Rarities:GetRarityData(b["RarityType"], "Stage"));
		b["Perk"] = "Multiples Strength By x"..tostring(b["StrengthMultiplier"]).." And Coins By x"..tostring(b["CoinsMultiplier"]..".");
		if(b["PlayerMorphing"]) then
			b["Perk"] = b["Perk"].." Allows Character Morphing";
		end;
		if not b["LinkedMorph"] then
			b["LinkedMorph"] = game:GetService("ReplicatedStorage"):WaitForChild("ShopItems"):WaitForChild("StageMorphs"):FindFirstChild(b["Names"]);
		end;
		local TradeStatus = "Yes";
		if(b["Non-Tradable"])then TradeStatus = "No" end;
		b["InventoryData"] = {
			{Name = "Strength Multiplier:", Value = "x"..tostring(b["StrengthMultiplier"])};
			{Name = "Coins Multiplier:", Value = "x"..tostring(b["CoinsMultiplier"])};
			{Name = "Character Morphing:", Value = tostring(b["PlayerMorphing"])};
			{Name = "Description:", Value = (b["Description"])};
			{Name = "Perks:", Value = b["Perk"]};
			{Name = "Store Price:", Value = Formatter.formatToGameStyle(b["Price"], "$")};
			{Name = "Store Pricing:", Value = b["PriceStat"]};
			{Name = "Can Trade:", Value = TradeStatus};
		};
	end
	return Data;
end;

return ReturnData();

