function module:GetRandomSound(Emote)
	if(Emote and Emote.Audios)then	
		local Audio = module.Audios[Emote.Audios[math.random(1,#Emote.Audios)]] or "";
			return Audio;
	end;return "";
end;

--//
function module:LoadEmoteProduct(Emotes, AudioPackage)
	local SelectedEmote;
if(Emotes)then
		local SelectionArray = {}
		for a,b in pairs(module.Shop.Emotes) do
			for x,k in pairs(Emotes) do
				if(k == b)then
					table.insert(SelectionArray, {Content = b, Name = a, castArray = k});
				end
			end
		end
		SelectedEmote = SelectionArray[math.random(1,#SelectionArray)];
	else
		SelectedEmote = "";
	end;
	local AudioToChooseFrom = SelectedEmote.Content;
	if(AudioPackage)then
		AudioToChooseFrom = {Audios = AudioPackage;};
	end;
	local SoundEffect = module:GetRandomSound(AudioToChooseFrom);
	return {
		Name = SelectedEmote.Name;
		Animation = SelectedEmote.Content.Anim;
		Audio = SoundEffect;
		Package = SelectedEmote;
	};
end;

function module:ApplyPropetiesToEmote(AnimationTrack, Name)
	if(AnimationTrack)then
		if(Name)then
			local Data = module.Shop.Emotes[Name];
			if(Data and Data.AnimationFilter)then
				Data.AnimationFilter(AnimationTrack);
			end
		end
	end;
end;

