function module:FilterForShop(array, HideOwns, sep)
	local Plr = game:GetService("Players").LocalPlayer;
if(not sep)then
		local new = {};
		for i,v in pairs(array) do
			if(v["HideFromShop"])then
				if(Plr:FindFirstChild(v["Names"], true))then
					new[i]=v;
				end
			else
				new[i]=v;
			end;
		end
	return new;
	end;
