function module.ExtractId(Player)
	if (typeof(Player) == "number") then
		return Player;
	end;
	if (typeof(Player) == "string") then
		local Id = 1
			pcall(function()Id = game:GetService("Players"):GetUserIdFromNameAsync(Player)end)
		return Id;
	end;
	if (typeof(Player) == "Instance") then
		return Player.UserId;
	end;
end;
