function module.ExtractName(Player)
	if (typeof(Player) == "number") then
		local Name = "ROBLOX";	
			pcall(function() Name = game:GetService("Players"):GetNameFromUserIdAsync(Player) end)
		return Name;
	end;
	if (typeof(Player) == "string") then
		return Player
	end;
	if (typeof(Player) == "Instance") then
		return Player.Name;
	end
end;

