function module:ApplyHoverHint(InstanceObject, Info)
	if(not Info)then return;end;
		local Plr = game.Players.LocalPlayer;
		local PlrSettings = Plr:WaitForChild("plrSettings",600);
		local HoverHints = PlrSettings:WaitForChild("Mouse Hover Hints");
		local HoverHints__ = Plr:WaitForChild("PlayerGui"):WaitForChild("HoverHints",600);
		local Mouse = Plr:GetMouse();
	local HoverHint = CreateHoverElement(Info);	HoverHint.Parent = HoverHints__;
	HoverHint.Name = InstanceObject.Name.." HoverListen"
	HoverHint.Visible=false;
	HoverHint.Position = UDim2.new(0, Mouse.X, 0, Mouse.Y) + UDim2.new(0,13,0,5);
	local Connection;
	local function Update()
		HoverHint.Position = UDim2.new(0, Mouse.X, 0, Mouse.Y) + UDim2.new(0,13,0,5);
	end;
	local EnterConnection = InstanceObject.MouseEnter:Connect(function()
		HoverHint.Visible = true;
		Connection = game:GetService("RunService").RenderStepped:Connect(Update)
	end);
	local LeaveConnection = InstanceObject.MouseLeave:Connect(function()
		HoverHint.Visible = false;
		if(Connection)then Connection:Disconnect();Connection=nil;end;
	end);
	local OnChildRemovedConnection;
if(Info.MainListenRemove)then
		OnChildRemovedConnection = Info.MainListenRemove.ChildRemoved:Connect(function(C)
				OnChildRemovedConnection:Disconnect();
				if(EnterConnection)then EnterConnection:Disconnect();end;EnterConnection=nil;
				if(LeaveConnection)then LeaveConnection:Disconnect();end;LeaveConnection=nil;
			if(Connection)then Connection:Disconnect();end;Connection=nil;
			HoverHint:Destroy();
		end)
	end;
end;

