local function ReturnData()
	local Data = {};
	for _,v in ipairs(Pets) do table.insert(Data, v) end;
	for _,b in ipairs(Data) do
		b["RarityData"] = (Rarities:GetRarityData(b["RarityType"], "Pet"));
		Rarities:ApplyExtraData(b, "Pets");
		b["InventoryData"] = {};	
		for q,w in pairs(b["Perks"]["Multipliers"]) do
			if(w>0)then
				table.insert(b["InventoryData"], {Name = q.." Multiplier:", Value =  "x"..tostring(w)});
			end;
		end;for q,w in pairs(b["Perks"]["Intervals"]) do
			if(w.value>0)then
				local TargetValueDesc = Formatter.formatToGameStyle(w.value).." every "..tostring(w.min).."-"..tostring(w.max).." seconds.";
				table.insert(b["InventoryData"], {Name = q.." Interval:", Value =  TargetValueDesc});
			end;
		end;
		table.insert(b["InventoryData"], {Name = "Obtainable From Egg:"; Value = tostring(b["OnSale"])});
	end
	return Data;
end;


return ReturnData();

