function module:GetRarityData(Name, Type)
	local Cat = module[Type];
	if(Cat)then
		for _,x in pairs(Cat) do
			if(x.RarityType == Name)then
				return x;
			end
		end
	end
end;

--//
function module:GetRarityDataEntire(Name, Type)
	local Cat = module[Type];
	if(Cat)then
		for _,x in pairs(Cat) do
			if(x.RarityType == Name)then
				return {
					RarityData = x;	
					EggData = module.EggPrices[x.RarityType];
				};
			end
		end
	end
end

--//
function module:ApplyExtraData(b, Type)
	local Base = ShopItems:FindFirstChild(Type);
if(Base)then	
	local Model = Base:FindFirstChild(b["Names"], true);
		b["LocalModel"] = Model;
	end;
	for a,x in pairs(module.EggPrices) do
		if(a == b["RarityType"]) then
			b["EggInfo"] = x;break;
		end
	end
end;


return module

