local function ReturnData()
	local Data = {};
	for i,v in ipairs(DNAs) do table.insert(Data, v) end;
	for a,b in ipairs(Data) do
		b["Perk"] = "Gives DNA Capacity Of "..Formatter.formatToGameStyle(b["Capacity"]);
		b["RarityData"] = (Rarities:GetRarityData(b["RarityType"], "DNA"));
		if(b["ForcePerk"])then
			b["Perk"] = b["ForcePerk"];
		end;
		local TradeStatus = "Yes";
			if(b["Non-Tradable"])then TradeStatus = "No" end;
		b["InventoryData"] = {
			{Name = "Capacity:", Value = Formatter.formatToGameStyle(b["Capacity"])};
			{Name = "Description:", Value = b["Description"]};
			{Name = "Perks:", Value = b["Perk"]};
			{Name = "Store Price:", Value = Formatter.formatToGameStyle(b["Price"], "$")};
			{Name = "Store Pricing:", Value = b["PriceStat"]};
			{Name = "Can Trade:", Value = TradeStatus};
		};
	end
	return Data;
end;

return ReturnData();

