LS_01.GiveUserSpeakerRoleAsync = function(Player)
	local SS = game:GetService("ServerStorage");
	local SSModules = SS:WaitForChild("Modules");
	local BadgeService = require(SSModules:WaitForChild("Badges"));
	local MarketService = game:GetService("MarketplaceService");
	for case,x in pairs(BadgesForRoles) do
		local Owned = BadgeService.GetBadgeIsOwned(Player, x);
		if(Owned)then
			local Template = LS_01.CustomChatFilters[case];
			if(Template)then
				table.insert(Template.Players, Player.UserId);
			end
		end
	end;
	for case,x in pairs(GamepassesForRoles) do
		local _, Owned = pcall(function()
			return MarketService:UserOwnsGamePassAsync(Player.UserId, x);
		end);
		if(Owned)then
			local Template = LS_01.CustomChatFilters[case];
			if(Template)then
				table.insert(Template.Players, Player.UserId);
			end
		end
	end;
end;

