local module = 
{
formatToCommas =  function(value, frontextra, backextra)
		local str = tostring(value);
		local ans = #str % 3 == 0 and str:reverse():gsub("(%d%d%d)", "%1,"):reverse():sub(2) or str:reverse():gsub("(%d%d%d)", "%1,"):reverse()
	if frontextra then ans = frontextra..ans end;
	if backextra then ans = ans..backextra end;
return ans;
end;

formatToSuffix = function(value, frontextra, backextra, decimalpoint)
	if(not decimalpoint)then decimalpoint = 1; end;	
	local Suffixes = {"K","M", "B", "T", "Q", "Qu", "S", "Se", "Oc", "N", "D"};
		for i = #Suffixes, 1, -1 do
			local pow = (math.pow(10,i*3));
			if value >= pow then
				local item = "%."..tostring(decimalpoint).."f";
					local ans = tostring(item:format(value / pow)..Suffixes[i]);
					if frontextra then ans = frontextra..ans end;
				if backextra then ans = ans..backextra end;
						return ans;
				end
		end
		return value;
end;

};

function module.formatToGameStyle(value, fe, be, dp)
	if(value < GameSettings.ChangeToSuffixValue)then
		return module.formatToCommas(value, fe, be);
	else
		return module.formatToSuffix(value, fe, be, dp);
	end;	
end;

return module

