function module:TriggerWorldEnter(TargetCamCFrame, CustomColor, TeleportCFrame, doFunction, FadeInWait, FadeAfterCam, Speed, FadeOutFrameAfter)
	if not FadeInWait then FadeInWait = 0 end;
	if not Speed then Speed = 1;end;
	local CamTweenInfo = TweenInfo.new(Speed, Enum.EasingStyle.Linear, Enum.EasingDirection.Out, 0, false);
	local Cam = workspace.CurrentCamera; local CamBeforeEnter = Cam.CameraType;
Cam.CameraType = Enum.CameraType.Scriptable; repeat wait() until Cam.CameraType == Enum.CameraType.Scriptable;
	local CamTween = TweenService:Create(Cam, CamTweenInfo, {CFrame = TargetCamCFrame});
	CamTween:Play();
if typeof(FadeInWait) == "number" and not FadeAfterCam then
	wait(FadeInWait)
end;
	if not CustomColor then CustomColor = Color3.fromRGB(255,255,255);end;
delay(.2, function()
		if not FadeAfterCam then
			FFH.FadeInFrame(CustomColor, true);
		end
end)
	CamTween.Completed:Connect(function()
		if FadeAfterCam then
			wait(FadeInWait)
			FFH.FadeInFrame(CustomColor, true);
		else
		delay(.7, function()
			FFH.FadeOutFrame();
			end)
		end;
		Cam.CameraType = CamBeforeEnter;
	if TeleportCFrame then
			TriggerTeleport:FireServer(TeleportCFrame);
		end;
	if doFunction then
		doFunction();		
	end;
		if FadeAfterCam and FadeOutFrameAfter then
			FFH.FadeOutFrame();
		end;
	end)
end;

