local module = {}

function module:ConvertToModel(Item, Parent, Attachmentparticle, CustomPP, weld)
	local NewModel = Instance.new("Model");
	local PP;
	if Item:FindFirstChild("HumanoidRootPart") then PP = Item:FindFirstChild("HumanoidRootPart") end; 
	local Cloned = Item:Clone();
	for i,v in ipairs(Cloned:GetChildren()) do
		v.Parent = NewModel;
	end;
	for _,g in ipairs(NewModel:GetDescendants()) do
		if g:IsA("Script") or g:IsA("LocalScript") or g:IsA("ModuleScript") then
			g:Destroy();
		else
			if g:IsA("BasePart") then
				g.Anchored = true;
				g.CanCollide = false;
				if PP == nil then
					PP = g;
				end;
			end;
		end
	end
if NewModel.PrimaryPart == nil then
	if CustomPP then
		NewModel.PrimaryPart = CustomPP;
	else
		NewModel.PrimaryPart = PP;
	end;
end;
	NewModel.Parent = Parent;
	--NewModel.Parent = Parent or NewFolder;
	NewModel.Name = Item.Name;
	if weld then
		for _,b in pairs(NewModel:GetChildren()) do
			if b:IsA("BasePart") then
				local Weld = Instance.new("Weld", b);
				Weld.Name = "weld";
				Weld.Part0 = b;
				Weld.Part1 = NewModel.PrimaryPart or CustomPP;
				Weld.C0 = b.CFrame:inverse();
				Weld.C1 = NewModel.PrimaryPart.CFrame:inverse();
			end
		end;
		for _,k in pairs(NewModel:GetChildren()) do
			if k:IsA("BasePart") then
				k.Anchored = false;
			end;
		end
	end
	if Attachmentparticle then
		if Attachmentparticle == true then
			local newAttach = ItemObtainedParticle:FindFirstChildWhichIsA("Attachment");
			if newAttach then
				local newNewAttachment = newAttach:Clone();
				newNewAttachment.Parent = NewModel.PrimaryPart;
			end
		else
			if Attachmentparticle:IsA("Attachment") then
				local newAttach = Attachmentparticle:Clone();
				newAttach.Parent = NewModel.PrimaryPart;
			end
		end
	end
	Cloned:Destroy();
		--if NewModel:FindFirstChild("Humanoid") then NewModel:FindFirstChild("Humanoid").Anchored = false;end;
	return NewModel;	
end;

