--//
function module.CreateAudio(AudioName, Id, Play, Volume, Looped, PlaybackSpeed, Type)
	if(Type)then
		if(WhiteListedAudios[Type])then
			table.insert(WhiteListedAudios[Type], AudioName);
		end
	end
	Volume = Volume or DefaultAudioManipulationProperties.Volume; Looped = Looped or DefaultAudioManipulationProperties.Looped;
	PlaybackSpeed = PlaybackSpeed or DefaultAudioManipulationProperties.PlayBackSpeed;
	local NewAudio = Instance.new("Sound", ClientAudios);
	NewAudio.Name = AudioName;
	NewAudio.SoundId = Id;
	NewAudio.PlaybackSpeed = PlaybackSpeed; NewAudio.Volume = Volume; NewAudio.Looped = Looped; NewAudio.PlaybackSpeed = PlaybackSpeed;
	table.insert(AudioCache, {Name = AudioName, Id = Id, Play = Play, PlaybackSpeed = PlaybackSpeed, Volume = Volume, Looped = Looped, Time = DefaultAudioManipulationProperties.Time, File = NewAudio, Muted = false;});
	if Play then
		module.ManipulateAudio(AudioName, {Play = true});
	end;
	return NewAudio;
end

--//
function module.MuteAudio(AudioName, Id)
	if(not Id)then Id = "ThisIsAnIgnoreItem!";end;
	for _,x in pairs(AudioCache) do
		if(x.Name == AudioName or x.Id == Id)then
			module.ManipulateAudio(AudioName, {Volume = 0})
			wait(.1)x.Muted = true;
		end
	end;
end;

--//
function module.UnmuteAudio(AudioName, Id)
	if(not Id)then Id = "ThisIsAnIgnoreItem!"end;
	for _,x in pairs(AudioCache) do
		if(x.Name == AudioName or x.Id == Id)then
			x.Muted = false;
			module.ManipulateAudio(AudioName, {Volume = x.Volume});
		end
	end;
end;


--//
function module.DestroyAudio(AudioName)
	for a,b in pairs(AudioCache) do
		if b.Name == AudioName then
			b.File:Destroy();
			table.remove(AudioCache, a);
		end
	end
end

--//
function module.ManipulateAudio(AudioName, Arg, Destroy)
		spawn(function()
	for a,b in pairs(AudioCache) do
			if b.Name == AudioName then
				if(b.Muted)then return end;
				if Arg then
					if Arg.ForceStop then
						local VolTween = TweenService:Create(b.File, TweenInfo.new(Arg.Time, TweenStyle, TweenDirection, 0, false), {Volume = 0})VolTween:Play(); 
						VolTween.Completed:Connect(function()b.File:Stop();end);
					end
			Arg.Time = Arg.Time or b.Time; Arg.Looped = Arg.Looped or b.Looped; Arg.PlaybackSpeed = Arg.PlaybackSpeed or b.PlaybackSpeed;
			if Arg.Play and not Arg.ForceStop then b.File:Play(); end;
					if Arg.Id and not Arg.ForceStop and Arg.Id ~= b.File.SoundId then local VolTween = TweenService:Create(b.File, TweenInfo.new(Arg.Time/2, TweenStyle, TweenDirection, 0, false), {Volume = 0, PlaybackSpeed = 0})VolTween:Play(); 
						VolTween.Completed:Connect(function()
							wait(.1)
							b.File.SoundId = Arg.Id;
							b.File:Play();
							local VolTween2 = TweenService:Create(b.File, TweenInfo.new(Arg.Time, TweenStyle, TweenDirection, 0, false), {Volume = Arg.Volume, PlaybackSpeed = Arg.PlaybackSpeed;})VolTween2:Play();
						end)
					end;
					if Arg.Volume ~= b.File.Volume and not Arg.ForceStop then
						if not Arg.Id then
							local VolTween3 = TweenService:Create(b.File, TweenInfo.new(Arg.Time, TweenStyle, TweenDirection, 0, false), {Volume = Arg.Volume, PlaybackSpeed = Arg.PlaybackSpeed;})						
							VolTween3:Play();
						else
							if Arg.Id == b.Id then
								local VolTween3 = TweenService:Create(b.File, TweenInfo.new(Arg.Time, TweenStyle, TweenDirection, 0, false), {Volume = Arg.Volume, PlaybackSpeed = Arg.PlaybackSpeed;})						
								VolTween3:Play();							
							end
						end
			end;
			--<
		end;
			if Destroy then
				b.File:Destroy();
				table.remove(AudioCache, a);
			end;
		end
		end;
	end)
end;
--
function module.ResetAudio(AudioName)
	for g,t in pairs(AudioCache) do
		if t.Name == AudioName then
			module.ManipulateAudio(AudioName, t);
		end
