local function fitToViewport(Model, ViewportCam, Viewport, Rotation, FOV, ViewportOffset)
	if not FOV then FOV = 3;end;
	if not ViewportOffset then ViewportOffset = 30;end;
	ViewportCam.FieldOfView = FOV;
	local function getSetback()
		local longestY, longestZ = 0, 0;
		for i,v in pairs(Model:GetDescendants()) do
			if v:IsA("BasePart") then
				if v.Size.Y > longestY then
					longestY = v.Size.Y;
				end
				if v.Size.Z > longestZ then
					longestZ = v.Size.Z;
				end
			end
		end
		local calculation = (longestY / (math.tan(math.rad(ViewportCam.FieldOfView/2)) * 2) + (longestZ / 2));
		return calculation;
	end;
		local HumanoidRootPart = Model:FindFirstChild("HumanoidRootPart") or Model.PrimaryPart;
		if not Rotation then Rotation = CFrame.Angles(0,math.rad(180),0) end;
		--if not Rotation then Rotation = CFrame.Angles(0,0,0) end;
	if HumanoidRootPart then
			ViewportCam.CFrame = Model.PrimaryPart.CFrame * Rotation * CFrame.new(0,0,(getSetback() + (ViewportOffset * 2)))
	end;
end;

