local module = {}

function module:CreateAspectViewport(Model, ...)
	local AsArray = ...;
	if(not ViewportCache[Model.Name])then	
		if not AsArray then AsArray = {} end;
		local AssetModel = ItemObtained:ConvertToModel(Model,nil,nil,nil,true);
		local Viewport = Instance.new("ViewportFrame");
		AssetModel.Parent = Viewport;
		local TempCam = Instance.new("Camera", Viewport);
		TempCam.CFrame = CFrame.new(0,0,0);
		AssetModel:SetPrimaryPartCFrame(CFrame.new(0,0,0));
		AssetModel.PrimaryPart.Anchored = true;
		TempCam.Name = "AspectViewportCamera";
		Viewport.CurrentCamera = TempCam;
		fitToViewport(AssetModel, TempCam, Viewport, AsArray.Rotation, AsArray.FOV, AsArray.ViewportOffset);
		local ViewportClone = Viewport:Clone();
		local CameraClone = TempCam:Clone();
		ViewportCache[Model.Name] = {
			Viewport = Viewport:Clone();
			Camera = TempCam:Clone();
		}
		return  {
			Viewport = Viewport;
			Camera = TempCam;
		};
	else
		local ViewportClone = ViewportCache[Model.Name].Viewport:Clone();
		local CameraClone = ViewportCache[Model.Name].Camera:Clone();
		ViewportClone.CurrentCamera = CameraClone;
		return {
			Viewport = ViewportClone;
			Camera = CameraClone;
		}
	end
end;

