local E = {
	Spin = function(x,i,z,f)
		if not i then i = 360;end;
		if not z then z = 4;end;
		if not f then f = 20;end;
		for b = 1,i,z do
			x.Icon.Rotation = x.Icon.Rotation+f;
			game:GetService("RunService").RenderStepped:Wait();
		end
	end;

	Scale = function(x,i,z)
		local OriginX = x.Icon.Size;
		if not z then z = 30 end;
		x.Icon:TweenSize(UDim2.new(OriginX.X.Scale, z, OriginX.Y.Scale, z), "In", "Linear", i);
	end;

	FadeOut = function(x,i,search)
		if not i then i = .1;end;
		for i = 0,1,i do
		if not search then
				x.Icon.ImageTransparency = i;
			else
				x[search] = i;
		end;
			game:GetService("RunService").RenderStepped:Wait();
		end
	end
}

