function module.ShowUIs(IgnoreList, Plr)
	if not Plr then Plr = game:GetService("Players").LocalPlayer;end;
	if IgnoreList then table.insert(IgnoreList, "DeveloperPanel") else IgnoreList = {"DeveloperPanel"}; end;
	if(Plr)then
		local PlrUI = Plr:WaitForChild("PlayerGui");
		for _,v in pairs(PlrUI:GetChildren()) do
			if v:IsA("ScreenGui") then
				local InIgnore = false;
			if(IgnoreList)then
				for _,x in pairs(IgnoreList) do
					if(x == v.Name or x == v) then
						InIgnore = true; break;
					end
				end;end;
				if not InIgnore then
					v.Enabled = true;
				end
			end
		end
	end;
end;

