function module.FilterStatGain(Plr, Stat, Value)
	local PlrStat = Plr:WaitForChild("leaderstats");
	local Matching = PlrStat:FindFirstChild(Stat);
	local Multiplies = {1};
	local Char = Plr.Character or Plr.CharacterAdded:Wait();
	local HumanRP = Char:WaitForChild("HumanoidRootPart");
	if(Plr and Stat and PlrStat and Matching)then

	-->Training Wise
		local Rayparams = RaycastParams.new();
		Rayparams.FilterType = Enum.RaycastFilterType.Whitelist;
		Rayparams.FilterDescendantsInstances = WorkspaceTrainingAreas;
		local Ray_ = workspace:Raycast(HumanRP.Position, Vector3.new(0,-25,0), Rayparams);
		if(Ray_)then
			local StatMultVal = (Ray_.Instance.TrainingArea:FindFirstChild(Stat));
			if(StatMultVal)then
				table.insert(Multiplies, StatMultVal.Value);
			end
		end;

	-->Gamepass wise
		local Gamepasses = (GamePassMultipliers[Stat]);
		if(Gamepasses)then
			local CachePlayer = MultiplierCacheData[Plr];
			if(CachePlayer)then
				for i,v in pairs(Gamepasses) do
					if(CachePlayer[i])then
						if(v > 0) then
							table.insert(Multiplies, v);
						end;
					end
				end
			else
			warn("User Had No Cached Data For Filtering: "..Plr.Name);
		end;
	end;
	-->Pet Wise
		local EquippedItems = EquippedGrabber.getEquippedItems(Plr)
		local EquippedPets = EquippedItems.Pets.module;
			for _,k in pairs(EquippedPets) do
			local Curr_M = k["Perks"]["Multipliers"][Stat];
				if(Curr_M) and (Curr_M > 0) then
					table.insert(Multiplies, Curr_M);
				end
			end;

	-->Stage Wise	
			local EquippedStage = EquippedItems.Stage.module;
			if(EquippedStage) and (EquippedStage["Names"]) then
				local StageMult = (EquippedStage[Stat.."Multiplier"]);
				if(StageMult)then
					if(StageMult > 0) then
						table.insert(Multiplies, StageMult);
					end
				end
			end;	
		local Final = Value;
		for _,v in ipairs(Multiplies) do
			Final = Final * v;
		end;
		return Final
	end;
	return Value;
end;


