function module:SetPlayerStat(Plr, TargetStatName, Value, Format)
	local PlrStat = Plr:WaitForChild("leaderstats");
	local Matching = PlrStat:FindFirstChild(TargetStatName);
	if Matching and Value then
		if TargetStatName == "Strength" then
			local CurrDNA = EquippedGrabber.getEquippedItems(Plr).DNA.module;
			if (CurrDNA["Capacity"]) then
				if Format == "add" then
					Value = math.clamp(Matching.Value+Value,0,CurrDNA["Capacity"]);
					Format = nil;
				end;
			end
		end
		if Format then
			if Format == "add" then
				Matching.Value = Matching.Value + Value;
			end;
			if Format == "subtract" then
				Matching.Value = math.clamp(Matching.Value - Value, 0, math.huge);
			end
		else
			Matching.Value = Value;
		end

	end 
end;

