function module:TakeItemFromUser(Player, ItemName, Category)
	local category_ = "plr"..string.upper(Category):sub(1,1)..string.sub(Category, 2, #Category).."s";

	Category = Player:FindFirstChild(category_);
		if(not Category)then return end;
	local instance = Category:FindFirstChild(ItemName, true);
	if(instance and instance:IsA("BoolValue") and instance:FindFirstChild("Copies")) then
		local Copies = (instance:FindFirstChild("Copies"));
		if(Copies.Value <=1)then
			module.RequestEquip(Player, Category:FindFirstChildWhichIsA("BoolValue"));
			module.RequestUnequip(Player, instance);
			instance:Destroy();	
			return true;
		else
			Copies.Value -= 1;return true;
		end
	end
end;


