function module:ProcessTrade(TradeProduct)
	if(TradeProduct)then
		local Player1 = TradeProduct.Sender;
		local Player2 = TradeProduct.Recipient;
		if not Player1 or not Player2 then return end;
		local P1InGameCheck = game:GetService("Players"):FindFirstChild(Player1.Name);
		local P2InGameCheck = game:GetService("Players"):FindFirstChild(Player2.Name);
		if(P2InGameCheck and P1InGameCheck)then
			local P1Offers = (TradeProduct.Offers[Player1.Name]);
			local P2Offers = (TradeProduct.Offers[Player2.Name]);
			if(#P1Offers <=0 and #P2Offers <=0)then return true;end;
				local _, failed = pcall(function()
					for _,x in pairs(P1Offers) do
						module:TakeItemFromUser(Player1, x.Moduled["Names"], x.TargetModule);
						module:RewardItem(Player2, x.Moduled["Names"], x.TargetModule);
					end	for _,x in pairs(P2Offers) do
						module:TakeItemFromUser(Player2, x.Moduled["Names"], x.TargetModule);
						module:RewardItem(Player1, x.Moduled["Names"], x.TargetModule);
					end;
			end);if(failed)then return false;end;
			return true;
		else
			return false;
		end
	end
end;

