function module:ResetPlayer(Player, ...)
	if (...) and (Player) then
		local Id = ExtractId(Player);
		local Name = ExtractId(Player);
	if(Id and Name)then
		local Final;local Array;
		if(typeof(...) == "string") then
			if(... == "wipe")then ExecuteWipe(Id, ...);return;end;
			Final = ResetTypes[...];
		end;
		if(typeof(...) == "table") then
			Final = ...;
		end;
		if(typeof(Final) == "table") then
			Array = BindToDefault(Final, DefaultReset);
			RunResetService(Id, Array)
		end
		end
	end;
end;

