		if Id == v.Id then
			local Destinations = v.Model:FindFirstChild("Destinations");
			local FocusObjects = v.Model:FindFirstChild("FocusObjects");
			if FocusObjects and Destinations then
				for a,b in pairs(FocusObjects:GetChildren()) do
					if UniqueId then
						if b.Name == UniqueId then
							b:Destroy();
						end
					end;
					if FocusObject and not UniqueId then
						if b.Value == FocusObject then
							b:Destroy();
						end
					end
				end
			end
		end
	end
