local function AddCameraShakeToNearUsers(Basepart, Magnitude)
	if not (Magnitude)then Magnitude = 100; end;
	if(#Players:GetPlayers() > 0)then
		for _,g in pairs(Players:GetPlayers())do
			local Char = g.Character or g.CharacterAdded:Wait();
			if(Char)then
				local HumanRP = Char:FindFirstChild("HumanoidRootPart");
				if(HumanRP)then
					if(HumanRP.Position - Basepart.Position).Magnitude < Magnitude then
						CameraShakeTranslator:FireClient(g, "AddCameraShake", "CameraShakeToNearUsers", 10, 1);
