local function RunAnimation(id, human, Basepart)
	local PrevWalkSpeed = human.WalkSpeed; human.WalkSpeed = 0;
	local NewAnimation = Instance.new("Animation", human.Parent);
	NewAnimation.AnimationId = id;
	local AnimationIn = human:LoadAnimation(NewAnimation);
		AnimationIn:Play();
		AnimationIn.Stopped:Connect(function()
			human.WalkSpeed = PrevWalkSpeed;
			NewAnimation:Destroy();
			AddCameraShakeToNearUsers(Basepart);
	end)
end;

