local function GetReadableTimeStamp(TimeStamp, Format)
	local Difference = TimeStamp - os.time();
		local Data = {
			Years = Difference/(60*60*8760);
			Months = Difference/(60*60*730.01);
			Weeks = Difference/(60*60*168);
			Days = Difference/(60*60*24);
			Hours = Difference/3600%24;
			Minutes = Difference/60%60;
			Seconds = Difference%60;
	};
	if not Format then
		return Data;
	end;
	if Format == "simple" then
		return string.format(
			"%iYr, %idM, %iW, %iD, %02dHr, %02dMin, %02dSec",
			Data.Years, Data.Months, Data.Weeks, Data.Days, Data.Hours, Data.Minutes, Data.Seconds
		);
	else
		return string.format(
			"%i Year(s), %i Month(s), %i Week(s), %i Days(s), %02d Hour(s), %02d Minute(s), %02d Second(s)",
			Data.Years, Data.Months, Data.Weeks, Data.Days, Data.Hours, Data.Minutes, Data.Seconds
		);
	end
end


