local function GetBestStageIndex(UserStages)
	local LastIndex = 0;
	for _,v in pairs(UserStages:GetChildren())do
		local Index = v:WaitForChild("StageIndex");
		if(Index and Index.Value > LastIndex)then
			LastIndex = Index.Value;
		end
	end;return LastIndex;
end

