local function setPets(queryplr, PetsTable)
	local t = {};
	local Pets = Instance.new("Folder", queryplr);
	Pets.Name = "plrPets";
	for i,v in pairs(Pets_Module) do
		for q,p in pairs(PetsTable) do
			if (p["Pet"] == v["Names"]) then
				table.insert(t, p);
			end
		end
		end;
	for index,z in ipairs(t) do
			local NewPet = Instance.new("BoolValue", Pets);
			NewPet.Name = z["Pet"];
			NewPet.Value = false;
			local NewPetLvl = Instance.new("IntValue", NewPet);
			NewPetLvl.Name = "Lvl";
			NewPetLvl.Value = z["Level"];
			local NewPetName = Instance.new("StringValue", NewPet);
			NewPetName.Name = "PetName"
			NewPetName.Value = z["PetName"];
			local NewPetKills = Instance.new("IntValue", NewPet);
			NewPetKills.Name = "Kills";
			NewPetKills.Value = z["Kills"];
			local NewPetCopies = Instance.new("IntValue", NewPet);
			NewPetCopies.Name = "Copies";
			NewPetCopies.Value = z["Copies"];
			for i,v in pairs(BUD_ServerDataS[queryplr].other.equippedPets) do
				if (v == z["Pet"]) then
				Statistics.RequestEquip(queryplr, NewPet);
			end
		end
	end;
end;
