local function setStages(queryplr, StageTable)
	local t = {};
	local Stages = Instance.new("Folder",queryplr);
	Stages.Name = "plrStages";
		for i,v in pairs(Stage_module)do
			for q,p in pairs(StageTable)do
				if(p.Name == v["Names"])then
					table.insert(t, {Name = v["Names"], Copies = p.Copies});
				end
			end	
		end
		for index,z in ipairs(t)do
			if not Stages:FindFirstChild(z.Name)then
				local stageitem = Instance.new("BoolValue", Stages);
				stageitem.Name = z.Name;
				stageitem.Value = false;
				local StageIndex = Instance.new("IntValue", stageitem);
				StageIndex.Name = "StageIndex";
				local Copies = Instance.new("IntValue", stageitem);
				Copies.Name = "Copies";Copies.Value = z.Copies;
			for g,t in ipairs(Stage_module) do
				if t["Names"] == z.Name then
							StageIndex.Value = t["Index"];
							BUD_ServerDataS[queryplr].statistics.stage = t["Index"];
						end
					end
			pcall(function()
				if(z.Name == BUD_ServerDataS[queryplr].other.equippedStage)then
					stageitem.Value = true;					
				end
			end)
			end
		end
		t = nil;
end
