local function setDumbs(queryplr, dumbtable)
	local t = {}
	local dumbs = Instance.new("Folder",queryplr);
	dumbs.Name = "plrDumbs";
		for i,v in pairs(Dumb_module)do
			for q,p in pairs(dumbtable)do
				if(p.Name == v["Names"]) then
					table.insert(t, {Name = v["Names"], Copies = p.Copies})
				end
			end
		end
	for _,z in pairs(t)do
		if not dumbs:FindFirstChild(z.Name)then
			local dumbitem = Instance.new("BoolValue", dumbs);
			dumbitem.Name = z.Name;
			dumbitem.Value = false;
			local Copies = Instance.new("IntValue", dumbitem);
			Copies.Name = "Copies";
			Copies.Value = z.Copies;
		pcall(function()
			if(z.Name == BUD_ServerDataS[queryplr].other.equippedDumb)then
				local Char = queryplr.Character or queryplr.CharacterAdded:Wait();
					if not Char:FindFirstChild(z.Name)then
						if queryplr.Backpack:FindFirstChild(z.Name) then return end;
				dumbitem.Value = true;
				local tool = Dumbs_Tool:FindFirstChild(z.Name):clone();
				tool.Parent = queryplr:WaitForChild("Backpack");
				end
			end end);
		end
	end
	t = nil
end

