--Loading BUD
local function loadBUD(queryplr)
		local ServerInfo = Instance.new("Folder", queryplr);
		ServerInfo.Name = "UserServerData"	
	local UserD;
		local Success,
			  Error = pcall(function()
				UserD = BasicUserData:GetAsync(queryplr.UserId);end);
		if Error then warn("Failed to load "..queryplr.Name.." BUD"..tostring(Error)) return; end;
if not UserD then
	UserD = createBUD(queryplr);
		TMM:FireClient(queryplr, true);
	else
		TMM:FireClient(queryplr, false);
end
	BUD_ServerDataS[queryplr] = UserD;
	setIslands(queryplr, UserD.islands);
	setDumbs(queryplr, UserD.items.dumbs);
	setDNAs(queryplr, UserD.items.DNAs);
	setStages(queryplr, UserD.items.stages)
	setSettings(queryplr, UserD.Settings);
	setPets(queryplr, UserD.items.pets)
		print("Successfully loaded "..queryplr.Name.."'s Basic User Data")
end
--Saving BUD
local function saveBUD(queryplr, leaving)
	if(#queryplr.plrDumbs:GetChildren() > 0) then	
if(not CurrSaving[queryplr])then
	CurrSaving[queryplr] = true;
	if(BUD_ServerDataS[queryplr])then
		local Success,
				  Error = pcall(function()
				local QueryLeaderstats = queryplr:FindFirstChild("leaderstats")
				BUD_ServerDataS[queryplr].statistics.coins = QueryLeaderstats["Coins"].Value;
				BUD_ServerDataS[queryplr].statistics.strength = QueryLeaderstats["Strength"].Value;
				BUD_ServerDataS[queryplr].statistics.kills = QueryLeaderstats["Kills"].Value;
				BUD_ServerDataS[queryplr].statistics.jumps = QueryLeaderstats["Jumps"].Value;
				BUD_ServerDataS[queryplr].statistics.gems = QueryLeaderstats["Gems"].Value;
				BUD_ServerDataS[queryplr].statistics.Exp = QueryLeaderstats["Exp"].Value;
				saveDumbs(queryplr);
				saveDNAs(queryplr);
				saveStages(queryplr);
				saveSettings(queryplr);
				savePets(queryplr);
				saveIslands(queryplr);
		local plrDumbs = queryplr:FindFirstChild("plrDumbs");
					for _,q in pairs(plrDumbs:GetChildren())do
						if(q.Value == true) then
							BUD_ServerDataS[queryplr].other.equippedDumb = q.Name;
						end
					end
		local plrDNAs = queryplr:FindFirstChild("plrDNAs");
					for _,k in pairs(plrDNAs:GetChildren())do
						if(k.Value == true) then
							BUD_ServerDataS[queryplr].other.equippedDNA = k.Name;
						end
					end

		local plrStages = queryplr:FindFirstChild("plrStages");
					for _,k in pairs(plrStages:GetChildren())do
						if(k.Value == true) then
							BUD_ServerDataS[queryplr].other.equippedStage = k.Name;
							BUD_ServerDataS[queryplr].statistics.stage = k.StageIndex.Value;
						end
					end;
		local plrPets = queryplr:FindFirstChild("plrPets");
				local Equipped = {};	
				for _,k in pairs(plrPets:GetChildren())do
					if(k.Value == true) then
							table.insert(Equipped, k.Name);
						end
					end;
				BUD_ServerDataS[queryplr].other.equippedPets = Equipped;
						BasicUserData:UpdateAsync(queryplr.UserId,function()
							 return BUD_ServerDataS[queryplr]
						end);
				print("Successfully saved "..queryplr.Name.."'s Basic User Data");
			end);
		if(Error)then
			warn("Failed to save "..queryplr.Name.." BUD [ERROR: "..Error.."]"); return; end;
		end
		wait(.1)
			CurrSaving[queryplr] = nil;
			if(leaving)then
				CurrSaving[queryplr]=nil;
			end
			end;
		else
		end;
end
