local function RequestClaim(Plr, Day)
	local RandomSelectionSheet = {"Dumb"};
	local FormattedDay = "Day "..tostring(Day);
	local FirstSelectionwave = RandomSelectionSheet[math.random(1,#RandomSelectionSheet)];
	if(FirstSelectionwave == "Dumb" and Rewards[FormattedDay]["Dumb"] == nil) then FirstSelectionwave = "Coins"; end;
	local AssetFolder = Rewards[FormattedDay][FirstSelectionwave];
	local SecondSelectionwave = AssetFolder[math.random(1,#AssetFolder)];
	if(FirstSelectionwave ~="Dumb")then
		Statistics:SetPlayerStat(Plr, FirstSelectionwave, SecondSelectionwave, "add");
	else
		Statistics:RewardItem(Plr, SecondSelectionwave, "dumb");
	end
	local Text = FormattedDay.." Reward Collected, Category ["..FirstSelectionwave.."] Reward: "..tostring(SecondSelectionwave);
	ServerChat:FireClient(Plr, {
		Text = Text;
		Color = Color3.fromRGB(37, 135, 247);	
	}, "onscreen");
	Statistics:SetPlayerStat(Plr, "Exp", math.random(1500,2500), "add");
end;

