local function OnRedeemCodeEvent(Plr, QueryCode)
	if CheckInGame(Plr) then
		if not CheckIfInQueue(Plr) then AddToQueue(Plr) 			
			local PlrStats = Plr:FindFirstChild("leaderstats");
			local PlrCoins = PlrStats:FindFirstChild("Coins");
			local PlrGems = PlrStats:FindFirstChild("Gems");	
			local PlrStrength = PlrStats:FindFirstChild("Strength");

			local Ran, Failed = pcall(function()
			if(not CodesServer)then	
				CodesServer = GetCodeData();
			end;
				local TargetCode = CodesServer[QueryCode];
				if TargetCode then
					if (TargetCode["Expiration"]["ForceExpired"]) then
						RedeemCodeEvent:FireClient(Plr, "Code Has Expired", Colors.Expired);
						return;
					end;
					if(os.time(TargetCode["Expiration"]["TimeStamp"]) - os.time()) < 0 then
						RedeemCodeEvent:FireClient(Plr, "Code Has Expired", Colors.Expired);
						return;
					end
					local MaximumRedeems = TargetCode["Expiration"]["MaximumRedeems"];
					if not (CheckIfUsedCode(Plr, QueryCode, MaximumRedeems)) then
						if(TargetCode["Reserved"])then
							local ReserveData = FilterReservedCode(Plr, TargetCode["Reserved"]);
							if(ReserveData.Error)then 
								RedeemCodeEvent:FireClient(Plr, ReserveData.Error, Colors.Expired);
								return;
							end;
						end;
						SaveNewCodeRedeem(Plr, QueryCode);
						RedeemCodeEvent:FireClient(Plr, "Code Redeemed", Colors.Redeemed)
						for stat,value in pairs(TargetCode["Stats"]) do
							if (value > 0) then
								Statistics:SetPlayerStat(Plr, stat, value, "add");
							end
						end;
						local DumbReward, StageReward, PetReward = TargetCode["Rewards"]["Dumb"],TargetCode["Rewards"]["Stage"],TargetCode["Rewards"]["Pet"];
						-->Dumbs
						if(DumbReward) then
							local MatchingDumb = ShopDumbs:FindFirstChild(DumbReward);
							if MatchingDumb then
								Statistics:RewardItem(Plr, MatchingDumb, "dumb", false, false, true);
								--ItemObtainedTranslator:FireClient(Plr, MatchingDumb, 5, "New Dumb! ["..MatchingDumb.Name.."], Equip From Your Inventory Or Shop");
							end;
						end;
						-->Stages
						if(StageReward) then
							Statistics:RewardItem(Plr, StageReward, "stage", false, false, true);
							local MatchingStage = ShopStagesMorphs:FindFirstChild(StageReward);
							if MatchingStage then
							--	ItemObtainedTranslator:FireClient(Plr, MatchingStage, 5, "New Stage! ["..MatchingStage.Name.."], Equip From Your Inventory Or Shop");
							end
						end;
						if(PetReward) then
							Statistics:RewardItem(Plr, PetReward, "pet", true, false, true);
							local MatchingPet;local Rarity;
								for _,a in pairs(ShopItems:FindFirstChild("Pets"):GetChildren()) do for _,b in pairs(a:GetChildren()) do if(b.Name == PetReward) then MatchingPet = b; Rarity = a.Name;break;end;end;end;
							if MatchingPet then
							--	ItemObtainedTranslator:FireClient(Plr, MatchingPet, 5, "New ("..Rarity..") Pet! ["..MatchingPet.Name.."], Equip From Your Inventory Or Shop");
							end
						end;
						return;
					else
						RedeemCodeEvent:FireClient(Plr, "You Have No More Copies Left", Colors.AlreadyRedeemed);
					end
				else
					RedeemCodeEvent:FireClient(Plr, "Code Doesn't Exist", Colors.Invalid);
				end
			end)
			if Failed then
				warn(Failed)
				RedeemCodeEvent:FireClient(Plr, "Something Wen't Wrong", Colors.Failed);
			end
	else
		RedeemCodeEvent:FireClient(Plr, "Please Wait Before Attempting To Redeem Another Code")
		end;
	end
end;

