local function AddToQueue(Plr, Queue)
	table.insert(Queue, Plr);
	delay(QueueWaitTime, function()
		for i,g in ipairs(Queue) do
			if g == Plr then
				table.remove(Queue, i);
			end
		end
	end);
end;

--//
local function CheckIfInQueue(Plr, Queue)
	for _,g in pairs(Queue) do
		if g == Plr then
			return true;
		end
	end;
	return false;
end;
