local function HandlePortalEvent(Plr, baseColor, PortalFolder, RequestDiscover)
	if(RequestDiscover) then
		local Char = Plr.Character or Plr.CharatcerAdded:Wait();
		local HumanRP = Char:WaitForChild("HumanoidRootPart");
		local SearchRay = Ray.new(HumanRP.Position, Vector3.new(0,-40,0));
		local Hit = workspace:FindPartOnRayWithWhitelist(SearchRay, {ISLANDS_MODELS});
		if (Hit) then
			local Island = Hit:FindFirstAncestorWhichIsA("Folder");
			if Island then
				Statistics:RewardItem(Plr, Island.Name, "island");
			end
		end
		return;
	end
	local UserServerData = Plr:FindFirstChild("UserServerData");
	local base = PortalFolder:FindFirstChild("base");
	if(UserServerData and base)then
		local User_Islands = UserServerData:FindFirstChild("Islands");
		if(User_Islands) then
			local MatchingIsland_INUSER = User_Islands:FindFirstChild(PortalFolder.Name);
			local MatchingIsland_MODEL = ISLANDS_MODELS:FindFirstChild(PortalFolder.Name);
			local T_C = base.CFrame:ToWorldSpace(CFrame.new(0,0,-9));
			if(MatchingIsland_MODEL.Name == "Main Island") then T_C = nil end;
			if (MatchingIsland_INUSER and MatchingIsland_MODEL) then
				WorldEnterTranslator:FireClient(Plr, T_C, baseColor);
				wait(.9);
				print(Plr)
				Teleporter.TeleportPlayer(Plr, MatchingIsland_MODEL:FindFirstChild("TP").CFrame)
			end
		end
	end
end

