local function FindClosestSell(Plr, origin)
	local Char = Plr.Character or Plr.CharacterAdded:Wait();
	local HumanRP = Char:WaitForChild("HumanoidRootPart");
	local PrevMag = (HumanRP.Position - origin.p).Magnitude;
	local TargetCFrame = origin;
	for _,v in pairs(Teleports:GetChildren()) do
		if(v:IsA("BasePart")) then
			if(v.Name == "SellTP") then
		local CurrMag = (HumanRP.Position - v.Position).Magnitude;
		if(CurrMag < PrevMag) then
			PrevMag = CurrMag; TargetCFrame = v.CFrame;
		end
			end;
	end;
	end;
	return TargetCFrame;
end;

