local function CheckIfInDebounce(Plr)
	for i,v in ipairs(GemRequestUsers) do
		if v == Plr then
			return true;
		end
	end
return false;
end
--
local function AddToDebounce(Plr)
	table.insert(GemRequestUsers, Plr);
	delay(1.5, function()
		for i,v in pairs(GemRequestUsers) do
			if v == Plr then
				table.remove(GemRequestUsers, i);
			end
		end
	end)
end
--//
GemRequestEvent.OnServerEvent:Connect(function(Plr, TargetGem)
	if not CheckIfInDebounce(Plr) then
		AddToDebounce(Plr);
	if TargetGem == nil then return end;
		local Values = TargetGem:FindFirstChild("GemInfo");
		local GemWorth = Values:FindFirstChild("GemAmt");
		if Values and GemWorth then
			local Obtained = Values:FindFirstChild("Obtained");
			if Obtained.Value == false then
				local Char = Plr.Character or Plr.CharacterAdded:Wait();
				Obtained.Value = true;
				local UpCFrame = CFrame.new(TargetGem.Position) * CFrame.Angles(0,450,0) + Vector3.new(0, 10, 0);
				local UpTween = TweenService:Create(TargetGem, TweenInfo.new(1, Enum.EasingStyle.Back, Enum.EasingDirection.Out, 0, false), {CFrame = UpCFrame});
				UpTween:Play();
				local CompConnection = UpTween.Completed:Connect(function()
					wait(.2);
					local HumanRP = Char:FindFirstChild("HumanoidRootPart");
					local PlrStats = Plr:FindFirstChild("leaderstats");
					if HumanRP then
						TargetGem.CanCollide = false;
						local NewCFrame = HumanRP.CFrame:toWorldSpace(CFrame.new(Vector3.new(0, 1, 0)));
						local MoveToTween = TweenService:Create(TargetGem, TweenInfo.new(.5, Enum.EasingStyle.Linear, Enum.EasingDirection.Out, 0, false), {CFrame = NewCFrame, Size = Vector3.new(1,1,1), Transparency = .5});
						MoveToTween:Play();
						MoveToTween.Completed:Connect(function()
								if PlrStats then
							Statistics:SetPlayerStat(Plr, "Gems",GemWorth.Value, "add");
								TargetGem:Destroy();
							else
								TargetGem:Destroy();
							end;
						end);
					else
						Statistics:SetPlayerStat(Plr, "Gems", GemWorth.Value, "add");
						TargetGem:Destroy();
					end
				end);
			end
		else
			TargetGem:Destroy();
		end
	end
end)

