local function SpawnGem(SpawnPoint, ParentGem, MaxForSure)
	local Values = SpawnPoint:FindFirstChild("Values");
	local Amt, Rate, Health, Size = Values:FindFirstChild("Amt"), Values:FindFirstChild("Rate"), Values:FindFirstChild("Health"), Values:FindFirstChild("Size");
	local minAmt, maxAmt, minRate, maxRate, minHealth, maxHealth, minSize, maxSize = Amt:FindFirstChild("min"),Amt:FindFirstChild("max"), Rate:FindFirstChild("min"),Rate:FindFirstChild("max"), Health:FindFirstChild("min"),Health:FindFirstChild("max"), Size:FindFirstChild("min"),Size:FindFirstChild("max");
local RandomAmt = math.random(minAmt.Value, maxAmt.Value);
local RandomHealth = math.random(minHealth.Value, maxHealth.Value);
local RandomSize = math.random(minSize.Value, maxSize.Value);
local RandomRotation = math.random(0,15);

	local LastCastValue;
	local CanPlace = false;
		if #ParentGem:GetChildren() <= 0 then
			local Vector = Vector3.new((-SpawnPoint.Size.X/2) + RandomSize * 0.5, (SpawnPoint.Size.Y/2) + (RandomSize - math.clamp(math.random(3,6), RandomSize/2, RandomSize * 3)) * 0.5, (-SpawnPoint.Size.Z/2) + RandomSize * 0.5)
			local StartCorner = SpawnPoint.CFrame:toWorldSpace(CFrame.new(Vector) * CFrame.Angles(0,0,0));
			LastCastValue = StartCorner;
		CanPlace = true;
