local PlayersInDebounce = {};

local function CheckDebounce(Plr)
	for i,v in pairs(PlayersInDebounce) do
		if v == Plr then
			return true;
		end
	end
	return false;
end;
--
local function AddToDebounce(Plr)
	table.insert(PlayersInDebounce, Plr);
	delay(.3, function()
		for i,v in pairs(PlayersInDebounce) do
			if v == Plr then
				table.remove(PlayersInDebounce, i);
			end
		end
	end)
end;
