local function OnPlatformInteraction(platform, Obj)
	local activated = platform:FindFirstChild("Activated");
	if activated then
		if Obj.Parent:FindFirstChild("Humanoid") and game:GetService("Players"):GetPlayerFromCharacter(Obj.Parent) then
			if not activated.Value == true then		
				activated.Value = true;
				platform.Platform.BrickColor = OnBrickColor;
				if PlatformC.Activated.Value == false then PlatformActivatedChat.Text = Obj.Parent.Name.." Activated "..string.upper(platform.Name);SendMessageToUsersInMine(PlatformActivatedChat); end;
				if PlatformA.Activated.Value == true and PlatformB.Activated.Value == true and PlatformC.Activated.Value == false then
					RevealPlatformC();
				end;
			end
		end
	end
end;
