local ATouch, BTouch, CTouch;
local Debounce = false;
--//
local function OnTouchKill(Touch)
	if Touch.Parent:FindFirstChild("Humanoid") and Touch.Parent.Humanoid.Health > 0 then
		if not Debounce then
			Touch.Parent.Humanoid:TakeDamage(Touch.Parent.Humanoid.MaxHealth+1);
			Debounce = true
			wait(.1); Debounce = false;
		end
	end
end
--//
local function OpenCave()
	ResetMineGem();
	Mine_lava_connection = Lava.Touched:Connect(OnTouchKill);Rising_lava_connection = RisingLava.Touched:Connect(OnTouchKill);
	CaveIsOpen.Value = true;
	SpawnMineMonsters();
	RisingLava.Position = RisingLavaPos.Start;
	ServerChat:FireAllClients(CaveIsOpenChat, "onscreen");
	ResetPlatforms();
ATouch, BTouch, CTouch = PlatformA.Platform.Touched:Connect(function(Obj) OnPlatformInteraction(PlatformA, Obj) end), PlatformB.Platform.Touched:Connect(function(Obj) OnPlatformInteraction(PlatformB, Obj) end), PlatformC.Platform.Touched:Connect(function(Obj) OnPlatformInteraction(PlatformC, Obj) end)
	for i = CaveOpenLifeTIme, 0, -1 do
		CaveTimeValue.Value = i;
		wait(1);
	end 
end;
--
local function CloseCave()
	if(Mine_lava_connection)then Mine_lava_connection:Disconnect();end;if(Rising_lava_connection)then Rising_lava_connection:Disconnect();end;
	ResetMineGem();
	CaveIsOpen.Value = false;
	RisingLava.Position = RisingLavaPos.Start;
	if ATouch then ATouch:Disconnect();end;if ATouch then BTouch:Disconnect();end;if ATouch then CTouch:Disconnect();end;
	ResetPlatforms();
	CleanUpMineMonsters();
	for i,v in pairs(GetPlayersInMine()) do
		pcall(function()
			v.Character.Humanoid:TakeDamage(v.Character.Humanoid.MaxHealth+1);
		end)
	end;
	--//
	for _,v in pairs(Players:GetPlayers()) do
		CameraShakeTranslator:FireClient(v, "RemoveCameraShake", "MineCollapseShake");
	end;
	PlayersInCave:ClearAllChildren();
	for i = CaveOpenWait, 0, -1 do
		CaveTimeValue.Value = i;
		wait(1);
	end
end

