--//
local function SignUp_ForBrawl(Player)
	if (LookingForUsers) then
		for a,b in ipairs(PlayersInBrawl) do
			if b.Player == Player then return end;
		end;
		table.insert(PlayersInBrawl, {
			Player = Player;
		})
	end;
end;

--//
local function SignUp_ForDied(Player)
	local WasInBrawl = false;
	for a,b in ipairs(PlayersInBrawl) do
		if b.Player == Player then WasInBrawl = true; table.remove(PlayersInBrawl, a) end;
	end;
	if(WasInBrawl)then
		table.insert(PlayersDiedFromBrawl_InOrder, {Player = Player});
	end;
end;

