local function TeleportQueuePlayers()
	if(#PlayersInBrawl>0)then
		for _,g in pairs(PlayersInBrawl) do
			local Player = g.Player;
			if(Player) then
				local Char = Player.Character or Player.CharacterAdded:Wait();
				if(Char) then
					local Human = Char:FindFirstChild("Humanoid");
					local HumanRP = Char:FindFirstChild("HumanoidRootPart");
					if(Human and Human.Health > 0 and HumanRP) then
						GetSpotAndTp(Player);
						if PlayersInCave:FindFirstChild(Player.Name) then
							PlayersInCave:FindFirstChild(Player.Name):Destroy();
						end
					end
				end
			end
		end;
	end;
end;

