while true do
	BaseInfo.Enabled = true;
	TimeCount.Visible = true;
	Header.Text = "Brawl Starts In:";
	for i = BrawlSettings.WaitTime, 0, -1 do
		local Minutes = math.floor(i/60%60);
		local Seconds = math.floor(i%60)
		local HumanReadable = string.format("%02i:%02i", Minutes, Seconds);
		TimeCount.Text = HumanReadable;
		wait(1);
	end;
	TimeCount.Visible = false; Header.Text = "Gathering Players...";BrawlEvent:FireAllClients("select");LookingForUsers = true;
	wait(BrawlSettings.SelectionTime);LookingForUsers = false;BrawlEvent:FireAllClients("select_ended");
	if(#PlayersInBrawl >= BrawlSettings.RequiredPlayers) then
		TeleportQueuePlayers();
		BrawlEvent:FireAllClients("start_countdown");
		Header.Visible = false;
		for i = 0,BrawlSettings.BrawlLifetime do
			if(#PlayersInBrawl <= 1) then
				warn("Everbody Died From Brawl");
				break;
			end;
			wait(1);
		end;
		local BrawlResults = {};
		for i = #PlayersInBrawl, 1,-1 do local Player = PlayersInBrawl[i].Player table.insert(BrawlResults, {
				Player = Player;
				Username = Player.Name;
				Image = ImageCache[Player] or DefaultImage;
				Kills = Player.leaderstats.Kills.Value;
				Wins = 0;
				Position = #BrawlResults+1;
			});end;
		for x = #PlayersDiedFromBrawl_InOrder, 1,-1 do local Player = PlayersDiedFromBrawl_InOrder[x].Player table.insert(BrawlResults, {
				Player = Player;
				Username = Player.Name;
				Image = ImageCache[Player] or "";
