--//
local function CheckAndRegisterPlayerForCooldown(Player)
	if(trade_out_bound_cool_down[Player])then return true end;
	trade_out_bound_cool_down[Player] = true;
	wait(.6);
	trade_out_bound_cool_down[Player] = nil;
end;

--//
local function SetUpTrade(TargetPlayer, SenderPlayer)
	local TargetPlayerSettings = TargetPlayer:WaitForChild("plrSettings");
	local TradeRequestsOn = TargetPlayerSettings:WaitForChild("Trade Requests");
	if(TradeRequestsOn.Value == false) then 
			TradeEvent:FireClient(SenderPlayer, "_trade_inbound_request_failed", "Requested Player Has Trade Inbounds Turned Off, Ask Them To Turn It On.")
		 return; end;
	for _,x in pairs(Trades) do
		if(x.Recipient == TargetPlayer or x.Recipient == SenderPlayer or x.Sender == TargetPlayer or x.Sender == SenderPlayer)then
			return false;
		end;
	end;
	if(game:GetService("Players"):FindFirstChild(TargetPlayer.Name) and game:GetService("Players"):FindFirstChild(SenderPlayer.Name)) then
		local TradeUp = {Recipient = TargetPlayer, Sender = SenderPlayer, Key = SenderPlayer.Name.."-"..TargetPlayer.Name.."-"..GameSettings.GenerateKey(10), Offers = {};
			AcceptState = {};IsProcessing = false;
		};
		TradeUp.AcceptState[TargetPlayer.Name] = false;
		TradeUp.AcceptState[SenderPlayer.Name] = false;
		TradeUp.Offers[TargetPlayer.Name] = {};
		TradeUp.Offers[SenderPlayer.Name] = {};
		table.insert(Trades, TradeUp);
		return TradeUp;
	end;
end;

--//
local function getTradeUpByKey(Key)
	for _,x in pairs(Trades) do
		if(x.Key == Key)then return x;end;
	end;
return nil;
end;


--//
local function OnTradeRequestDeclined(Key)
	for i,x in pairs(Trades) do
		if(x.Key == Key) then
			table.remove(Trades, i);x=nil;
		end
	end;
end;

--//
local function OnTradeRequestAccepted(Key)
	local TradeItem;
	for _,x in pairs(Trades) do
		if(x.Key == Key) then
			if not x.IsInTradeMode then
				x.IsInTradeMode = true;
				TradeItem = x;break;
			end;
		end
	end;
	if not TradeItem then return OnTradeRequestDeclined(Key);end;
	local ClientInfo = {
		Sender = TradeItem.Sender;
		Recipient = TradeItem.Recipient;
		TradeKey = TradeItem.Key;
	};
	local SenderPlayer = Players:FindFirstChild(TradeItem.Sender.Name);
	local TargetPlayer = Players:FindFirstChild(TradeItem.Recipient.Name);
	if(SenderPlayer and TargetPlayer)then
		TradeEvent:FireClient(SenderPlayer, "_trade_in_focus", ClientInfo);
		TradeEvent:FireClient(TargetPlayer, "_trade_in_focus", ClientInfo);
	else
		OnTradeRequestDeclined(Key);
	end
end;

