local function getModuled(module, name)
	for _,x in pairs(module) do
		if (x["Names"] == name) then
			return {moduled = x; module = module};
		end
	end
end
--//
local function MatchItemNameToProduct(Plr, Name)
	local Item = Plr:FindFirstChild(Name, true);
	if not Item:IsA("BoolValue") then return end;
	if not Item:FindFirstChild("Copies")then return end;
	local Copies = Item:FindFirstChild("Copies").Value;
	if Copies < GameSettings.Trading.RequiredCopiesForTrade then return end;
	return Item;
end;local function SearchArrayForName(Name, Array)
	for _,x in pairs(Array) do
		if(x["Names"] == Name)then
			return x;
		end
	end
end;local function GetProductModuled(Product)
	local x;
	for a,g in pairs(ModulesSearch) do
		local Pr = SearchArrayForName(Product.Name, g);
		if(Pr)then x = {Moduled = Pr; ModuleName = a}; break end;
	end
	return x;
end;


--//
local function CheckIfProductIsAlreadyOffered(Offers, ProductKey)
	for _,x in pairs(Offers) do
		if(x.ProductKey == ProductKey)then 
			return true;
		end
	end;
	return false;
end;

--//
local function RemoveProductFromOfferList(ProductKey, List)
	for s,x in pairs(List) do
		if(x.ProductKey == ProductKey)then
			table.remove(List, s);break;
		end
	end;
end;

--//
local function SendDataToTraders(TradeUp, Type, ...)
	TradeEvent:FireClient(TradeUp.Recipient, Type, ...);
	TradeEvent:FireClient(TradeUp.Sender, Type, ...);
end;


--//
local function AddToOfferList(Plr, Key, Product, ProductKey)
	local TradeUp = getTradeUpByKey(Key);
	if(TradeUp) then
		local UserOffers = TradeUp.Offers[Plr.Name];
		if(UserOffers)then
			if(not CheckIfProductIsAlreadyOffered(UserOffers, ProductKey))then	
				if(#UserOffers >= GameSettings.Trading.MaximumProductItems)then return; end;	
				Product["ProductKey"] = ProductKey;
				table.insert(TradeUp.Offers[Plr.Name], Product);
				SendDataToTraders(TradeUp, "_update_users_offer_list", TradeUp.Offers, TradeUp.AcceptState);
			else
				RemoveProductFromOfferList(ProductKey, UserOffers);
				SendDataToTraders(TradeUp, "_update_users_offer_list", TradeUp.Offers, TradeUp.AcceptState);
			end;
		end
	end
end;

--//

local function DeclineTrade(Key)
	local TradeUp = getTradeUpByKey(Key);
	if(TradeUp)then
		if not(TradeUp.IsProcessing)then
			TradeUp.IsProcessing = true;
			SendDataToTraders(TradeUp, "_global_trade_declined");
			OnTradeRequestDeclined(Key)
		end
	end
end;
--//
local function AcceptTrade(Key)
	local Tradeup = getTradeUpByKey(Key);
	if(Tradeup)then
		if not(Tradeup.IsProcessing)then
			Tradeup.IsProcessing = true;
				TradeEvent:FireClient(Tradeup.Recipient, "_trade_processing");
				TradeEvent:FireClient(Tradeup.Sender, "_trade_processing");
			local TradeProcessed = Statistics:ProcessTrade(Tradeup);
			wait(math.random(2,4));
			if(TradeProcessed)then
				TradeEvent:FireClient(Tradeup.Recipient, "_trade_sucessfully_processed");
				TradeEvent:FireClient(Tradeup.Sender, "_trade_sucessfully_processed");
			else
				TradeEvent:FireClient(Tradeup.Recipient, "_trade_failed");
				TradeEvent:FireClient(Tradeup.Sender, "_trade_failed");
			end
	OnTradeRequestDeclined(Key);
		end;
	end
end;

--//
TradeEvent.OnServerEvent:Connect(function(Plr, Type, ...)
	local Args = {...};

	local Key = Args[1];
	--print(Key, Args[1], Args[2])
	local TradeUp = getTradeUpByKey(Args[1]);

	if(TradeUp)then if(TradeUp.IsProcessing)then return end;  TradeUp.AcceptState[Plr.Name] = false;end;

	if(Type == "_global_trade_declined") then
		DeclineTrade(Key);
	end;

	if(Type == "_client_user_revoked")then
		if(TradeUp)then
		--	TradeUp.AcceptState[Plr.Name] = false;
			SendDataToTraders(TradeUp, "_update_users_offer_list", TradeUp.Offers, TradeUp.AcceptState);
		end
	end;
	if(Type == "_client_user_accepted")then
		if(TradeUp)then
			TradeUp.AcceptState[Plr.Name] = true;
			SendDataToTraders(TradeUp, "_update_users_offer_list", TradeUp.Offers, TradeUp.AcceptState);
			local accepts = 0;
			for a,x in pairs(TradeUp.AcceptState) do
				if(x==true)then
					accepts+=1;
				end;
			end;
			-->UPDATE
			if(accepts >= 2) then
				AcceptTrade(Key);
			end
		end
	end

	if(Type == "_trade_request_declined")then
		OnTradeRequestDeclined(Args[1]);
	end;
	if(Type == "_trade_request_accepted")then
		OnTradeRequestAccepted(Args[1]);
	end;
	if(Type == "_add_item_to_trade_list")then
		local ProductName = Args[2];
		local Product = MatchItemNameToProduct(Plr, ProductName);
		if(Product)then
			local ItemModuled = GetProductModuled(Product);
			if(ItemModuled)then
				local Moduled = ItemModuled.Moduled;
				local TargetModule = ItemModuled.ModuleName;
				if(Moduled and TargetModule)then
					AddToOfferList(Plr, Args[1], {Name = ProductName, Moduled = Moduled, TargetModule = TargetModule}, Args[3]);
				end;
			end
		end
	end;

	if(Type == "_trade_outbound_request") then
		local TargetPlayer = Args[1];
	if(TargetPlayer.Name == Plr.Name or TargetPlayer == Plr)then return end;
		if not CheckAndRegisterPlayerForCooldown(TargetPlayer) and not CheckAndRegisterPlayerForCooldown(Plr)then
			local TradeAttempt = SetUpTrade(TargetPlayer, Plr);
			if(TradeAttempt)then
				TradeEvent:FireClient(TradeAttempt.Recipient, "_trade_inbound_request", TradeAttempt.Sender, TradeAttempt.Key);
			else
				--<Something went wrong server side;
				TradeEvent:FireClient(Plr, "_trade_inbound_request_failed", "Player Is Already In A Trade Or Is Currently Recieving A Trade Request From Someone Else.")
			end

		else
			TradeEvent:FireClient(Plr, "_trade_inbound_request_failed", "Slow Down With Your Trade Requests Please.")
		end
	end

end);

