DeveloperPanel.OnServerEvent:Connect(function(Player, HexKey_Called, CalledFunction, ...)
	if(not Cooldown[Player])then
		Cooldown[Player] = true;delay(.2, function() Cooldown[Player] = nil;end);
		local HasPanel = PlayersWithPanelAccess[Player.Name] or PlayersWithPanelAccess[Player.UserId];
		if(not HasPanel)then CastBanToWrongCall(Player) return end;
		if(HexKey_Called ~= HexKey)then CastBanToWrongCall(Player); return end;
		local Command = AllowedCmds[CalledFunction];
		if(not Command)then CastBanToWrongCall(Player); return end;
		local AsArray = {...};
		if(#AsArray == Command.ArgCount)then

			if(HasPanel < Command.RequiredRank)then ServerChat:FireClient(Player, {Text = "You can't do that";Color = Color3.fromRGB(49, 178, 214);Position = UDim2.new(.5,0,.85,0);}, "onscreen") return end;
			local TargetId = GameSettings.ExtractId(AsArray[1]);
			if(PlayersWithPanelAccess[TargetId] and PlayersWithPanelAccess[TargetId] > HasPanel) then
				ServerChat:FireClient(Player, {
									Text = "Player Is Immune.";
									Color = Color3.fromRGB(49, 178, 214);
									Position = UDim2.new(.5,0,.85,0);
				}, "onscreen");
				return
			end
			Command.Function(Player, {...});
				ServerChat:FireClient(Player, {
					Text = "Command Executed.";
					Color = Color3.fromRGB(49, 178, 214);
					Position = UDim2.new(.5,0,.85,0);
				}, "onscreen");return;
		end
	end
end);

