			RightPunchInHuman:Play();
	RightPunchInHuman:GetMarkerReachedSignal("Swing"):Connect(function(Type)
if Type == "start" then
	AnimationDMGHandler.HitSearcher = RightHand;
	AnimationDMGHandler.CanDamage = true;
	AnimationDMGHandler.Character = Char;
end;
if Type == "end" then
	AnimationDMGHandler.CanDamage = false;
	AnimationDMGHandler.HitSearcher = nil;
	AnimationDMGHandler.Character = nil;
		wait(PunchWait);
	AnimationDMGHandler.DidDamge = false;
	IsPunching = false;
		if TouchSearchConnect then
			TouchSearchConnect:Disconnect();
		end
end;
	end)
			end
	end
end)


