--//
local function RunDamage(Sender, Reciever, ActualPlayer, ItemType, PlatformNotActivated)
	local SenderPlr = game:GetService("Players"):GetPlayerFromCharacter(Sender);
	local RecieverPlr = game:GetService("Players"):GetPlayerFromCharacter(Reciever);
	local SenderHuman = Sender:FindFirstChild("Humanoid");
	local SenderHumanRP = Sender:FindFirstChild("HumanoidRootPart");
	local SenderPlrStrength = SenderPlr:FindFirstChild("leaderstats"):FindFirstChild("Strength");
	AnimationDMGHandler.DidDamge = true;
	HitAudio:Play();
	if not ActualPlayer then
		if ItemType == "Gem" then
			local Humanoiditem = Reciever:FindFirstChildWhichIsA("Humanoid");
			if Humanoiditem and Humanoiditem.Health > 0 then
				local BaseDamage = math.clamp(SenderPlrStrength.Value/GameSettings.Character.StrengthToFistDamageDivider, GameSettings.Character.MinStrengthToFistDamage, GameSettings.Character.MaxStrengthToFistDamage);
				Humanoiditem:TakeDamage(BaseDamage)
			end;
			return;
		end;
		if ItemType == "MineGem" then
			if not PlatformNotActivated then
				Statistics:SetPlayerStat(SenderPlr, "Gems", math.random(GameSettings.Cave.MinGemPunch,GameSettings.Cave.MaxGemPunch), "add");
				Statistics:SetPlayerStat(SenderPlr, "Exp", math.random(300,700), "add");
			else
				ServerChat:FireClient(SenderPlr, {Theme = "Error", Text = "All Platforms Need To Be Activated"}, "onscreen")
			end;
			return;
		end;
		if ItemType == "Boss" then
			local KillContributers = Reciever:FindFirstChild("KillContributers");
			local Humanoiditem = Reciever:FindFirstChildWhichIsA("Humanoid");
			if Humanoiditem and Humanoiditem.Health > 0 then
				local BaseDamage = math.clamp(SenderPlrStrength.Value/GameSettings.Character.StrengthToFistDamageDivider, GameSettings.Character.MinStrengthToFistDamage, GameSettings.Character.MaxStrengthToFistDamage);
				Humanoiditem:TakeDamage(BaseDamage);
				if (KillContributers)then
					if KillContributers:FindFirstChild(Sender.Name) then
						KillContributers:FindFirstChild(Sender.Name):Destroy();end;
						local New = Instance.new("BoolValue", KillContributers);
						New.Name = Sender.Name;
							DebrisService:AddItem(New, 35);
				end
			end;			
			return;
		end;
		if ItemType == "CaveMonster" then
			local Humanoiditem = Reciever:FindFirstChildWhichIsA("Humanoid");
			if Humanoiditem and Humanoiditem.Health > 0 then
				local BaseDamage = math.clamp(SenderPlrStrength.Value/GameSettings.Character.StrengthToFistDamageDivider, 65, GameSettings.Character.MaxStrengthToFistDamage);
				Humanoiditem:TakeDamage(BaseDamage);
				if(Humanoiditem and Humanoiditem.Health <=0) then
					Statistics:SetPlayerStat(SenderPlr, "Gems", math.random(20,40), "add");
					Statistics:SetPlayerStat(SenderPlr, "Exp", math.random(90,150), "add");
				end
			end
		end
		return;
	end
	local RecieverHuman = Reciever:FindFirstChild("Humanoid");
	local RecieverHumanRP = Reciever:FindFirstChild("HumanoidRootPart");
	local BaseDamage = math.clamp(SenderPlrStrength.Value/GameSettings.Character.StrengthToFistDamageDivider, GameSettings.Character.MinStrengthToFistDamage, GameSettings.Character.MaxStrengthToFistDamage);
	local WhipLastAnim = RecieverHuman:LoadAnimation(OnHitAnimation);
	local MightTeaChar = Reciever:FindFirstChild("MightTea's");
	local AttackersFolder = MightTeaChar:FindFirstChild("Attackers");
	if(RecieverPlr:WaitForChild("UserServerData"):WaitForChild("IsInSafeZone").Value == true)then return end;
		if AttackersFolder then
			local NumberOfCurrAttackers = #AttackersFolder:GetChildren();
		if NumberOfCurrAttackers <= MaxAttackers then
			if AttackersFolder:FindFirstChild(SenderPlr.Name) then AttackersFolder[SenderPlr.Name]:Destroy(); end;
				local NewAttacker = Instance.new("ObjectValue");
				NewAttacker.Name = SenderPlr.Name;
				NewAttacker.Value = SenderHumanRP;
				NewAttacker.Parent = AttackersFolder;
			DebrisService:AddItem(NewAttacker, AttackerAddItemTime);
		end
	end
RecieverHuman:TakeDamage(BaseDamage)
WhipLastAnim:Play();
	spawn(function()
		if RecieverHumanRP and SenderHumanRP then
	for _,g in pairs(RecieverHumanRP:GetChildren()) do
		if g:IsA("BodyVelocity") and g.name == "PunchVelocity" then
			g:Destroy();
		end
	end
			local BodyVelocity = Instance.new("BodyVelocity", RecieverHumanRP);
			BodyVelocity.Name = "PunchVelocity";
			BodyVelocity.Velocity = Vector3.new(SenderHumanRP.CFrame.LookVector.X, 0, SenderHumanRP.CFrame.LookVector.Z).unit * 2;
			local Particle = OnFistHitParticle:Clone();
			Particle.Parent = RecieverHumanRP;
			Particle.Enabled = false;
			Particle:Emit(2);
		wait(1);
			Particle:Clear();
			Particle:Destroy();
				if BodyVelocity then
					BodyVelocity:Destroy();
				end
		end
	end)
end

--//
local function onTouch(C)
		pcall(function()
	if (AnimationDMGHandler.CanDamage) and (AnimationDMGHandler.Character) then
		if not C:IsDescendantOf(AnimationDMGHandler.Character) then
					if not AnimationDMGHandler.DidDamge then
						local MatchingPlr = game:GetService("Players"):GetPlayerFromCharacter(C.Parent);
						if MatchingPlr then
							RunDamage(AnimationDMGHandler.Character, C.Parent, true);
							return;
						end;
						if C.Parent:FindFirstChild("Gem_Protective_Layer") then
							RunDamage(AnimationDMGHandler.Character, C.Parent, false, "Gem");
							return;
						end;
						if C.Parent:FindFirstChild("IsBoss") then
							RunDamage(AnimationDMGHandler.Character, C.Parent, false, "Boss");
							return;
						end;
						if C.Parent:FindFirstChild("isCaveMonster") then
							RunDamage(AnimationDMGHandler.Character, C.Parent, false,  "CaveMonster");	
							return;
						end;
				if C.Name == "MineGem" then
					if C:FindFirstChild("minegem_allowhit") then
							RunDamage(AnimationDMGHandler.Character, C.Parent, false, "MineGem");
						else
							RunDamage(AnimationDMGHandler.Character, C.Parent, false, "MineGem", true);
						end;	
					end;
						end
				end
			end
		end)
end
--//
while true do
		if AnimationDMGHandler.HitSearcher then
			if AnimationDMGHandler.CanDamage then
				TouchSearchConnect = AnimationDMGHandler.HitSearcher.Touched:Connect(onTouch);
			else
				if TouchSearchConnect then
					TouchSearchConnect:Disconnect();
				end
			end
		end
	wait();
end

