local Char = script.Parent.Parent;
local Plr = game:GetService("Players"):GetPlayerFromCharacter(Char)
local Human = Char:WaitForChild("Humanoid");
local HumanRP = Char:WaitForChild("HumanoidRootPart");
Char:WaitForChild("Health"):Destroy();


while Char and Plr do
	local isInSafeZone0 = Plr:FindFirstChild("UserServerData");
if isInSafeZone0 then
		local isInSafeZone = isInSafeZone0:FindFirstChild("IsInSafeZone");
if isInSafeZone then
		if isInSafeZone.Value ~= false then
			if Human.Health ~= 0 then
			spawn(function()
				if Human.Health < 100 and Human.Health > 0 then
					Human.Health = Human.Health + 0.1;
				end
			end)
		if not HumanRP:FindFirstChild("HealthRegenParticle") then
				local HealthRegenParticle = Instance.new("ParticleEmitter", HumanRP);
				HealthRegenParticle.Name = "HealthRegenParticle";
				HealthRegenParticle.LockedToPart = true;
				HealthRegenParticle.Texture = "rbxassetid://13890082";
				HealthRegenParticle.Rate = 5;
				HealthRegenParticle.Lifetime = NumberRange.new(1)
				HealthRegenParticle.Enabled = true;
					end
		else
				for _,v in pairs(HumanRP:GetChildren()) do
					if v.Name == "HealthRegenParticle" then
						v:Destroy()
					end
				end
			end
	else
	pcall(function()
		for _,v in pairs(HumanRP:GetChildren()) do
			if v.Name == "HealthRegenParticle" then
				v:Destroy()
			end
		end
	end)
			end;
		end
	end;
wait()
end

